def fn(x):
    # QWERTY order for the 26 letters
    qwerty = "qwertyuiopasdfghjklzxcvbnm"
    # build lower‑case mapping a->q, b->w, …
    lower_map = {chr(ord('a') + i): qwerty[i] for i in range(26)}
    # upper‑case mapping A->Q, B->W, …
    upper_map = {k.upper(): v.upper() for k, v in lower_map.items()}

    result = []
    for ch in x:
        if ch.islower():
            result.append(lower_map.get(ch, ch))
        elif ch.isupper():
            result.append(upper_map.get(ch, ch))
        else:
            result.append(ch)          # keep any non‑letters unchanged
    return "".join(result)

